#[test]
fn indent_zero_prints_newlines_without_indentation_7605() -> Result<()> {
    for (args, stdin, want, want_code) in ROWS {
        let (stdout, stderr, code) = run_jq_full(args, Some(stdin))?;
        assert_eq!(
            (stdout.as_str(), code),
            (*want, *want_code),
            "{args:?} over {stdin:?}; stderr {stderr:?}"
        );
    }
    Ok(())
}

